<div class="d-flex justify-content-between align-items-center mb-4"><div><h3>لوحة موظف المنصة</h3><p class="text-muted mb-0">متابعة تشغيلية بصلاحيات أقل من مدير النظام.</p></div></div><div class="row g-3 mb-4"><?php foreach([['الطلبات',(int)$stats['requests'],'primary'],['الطلبات الجديدة/المعلقة',(int)$stats['pending'],'warning'],['مقدمو الخدمة النشطون',(int)$stats['providers'],'success'],['التقييمات',(int)$stats['reviews'],'info'],['الشكاوى المفتوحة',(int)$stats['open_complaints'],'danger']] as $c): ?><div class="col-6 col-xl"><div class="card p-3 h-100"><div class="small text-muted"><?= e($c[0]) ?></div><div class="fs-4 fw-bold text-<?= $c[2] ?>"><?= number_format($c[1]) ?></div></div></div><?php endforeach; ?></div><div class="card p-3"><h5>آخر الطلبات</h5><div class="table-responsive"><table class="table"><thead><tr><th>الطلب</th><th>العميل</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody><?php foreach($recentRequests as $r): ?><tr><td><?= e($r['request_number']) ?></td><td><?= e($r['customer_name'] ?? '-') ?></td><td><?= statusBadge($r['status']) ?></td><td><?= e($r['created_at']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= url('/employee/requests/'.$r['id']) ?>">عرض</a></td></tr><?php endforeach; ?></tbody></table></div></div>